const j = $json || {};
const jobId = (j.jobId || "").trim();
const assetKey = (j.assetKey || "").trim();
const assetType = (j.assetType || "featured_image").trim();
const language = j.language || "ar";
const headline = (j.headline || "").trim();
const mode = j.mode || "generate_background_and_render_text";
const validModes = ["existing_drive_image", "generate_background_and_render_text", "render_from_template"];
const driveFileId = j.driveFileId || null;

if (!jobId) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "jobId is required for featured image generator." };
}
if (!assetKey) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "assetKey is required for featured image generator." };
}
if (!assetType) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "assetType is required for featured image generator." };
}
if (!headline && mode !== "existing_drive_image") {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "headline is required for image generation mode " + mode };
}
if (!validModes.includes(mode)) {
  return { ok: false, errorCode: "INVALID_MODE", errorMessage: "mode must be one of: " + validModes.join(", ") };
}
if (mode === "existing_drive_image" && !driveFileId && (!$input.item.binary || !$input.item.binary.data)) {
  return { ok: false, errorCode: "DRIVE_FILE_MISSING", errorMessage: "driveFileId or binary input is required for existing_drive_image mode." };
}

return {
  jobId,
  assetKey,
  assetType,
  language,
  mode,
  headline,
  subheadline: j.subheadline || "",
  driveFileId,
  brandConfig: j.brandConfig || { brandName: "Mohamed Arslan", primaryColor: "#38bdf8" },
  ok: true
};

const p = $("02 Validate Parameters").item.json;
const mode = p.mode;
const brand = p.brandConfig || {};
const brandName = escapeXml(brand.brandName || "Mohamed Arslan");
const primaryColor = brand.primaryColor || "#38bdf8";

function escapeXml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function wrapText(text, maxCharsPerLine = 35) {
  if (!text) return [];
  const words = text.split(/\s+/);
  const lines = [];
  let currentLine = "";
  for (const word of words) {
    if ((currentLine + " " + word).trim().length <= maxCharsPerLine) {
      currentLine = (currentLine + " " + word).trim();
    } else {
      if (currentLine) lines.push(currentLine);
      currentLine = word;
    }
  }
  if (currentLine) lines.push(currentLine);
  return lines.slice(0, 3);
}

const rawH = p.headline || "";
const rawSub = p.subheadline || "";
const isRtl = /[\u0600-\u06FF]/.test(rawH);
const hLines = wrapText(rawH, 30).map(escapeXml);
const subLines = wrapText(rawSub, 40).map(escapeXml);
const width = 1200;
const height = 630;

const textDir = isRtl ? 'direction="rtl" text-anchor="end"' : 'text-anchor="start"';
const hX = isRtl ? 1120 : 80;
const subX = isRtl ? 1120 : 80;
const brandX = isRtl ? 80 : 1120;
const brandAnchor = isRtl ? 'text-anchor="start"' : 'text-anchor="end"';

const headlineSvgNodes = hLines.map((line, idx) => {
  const y = 240 + idx * 56;
  return `<text x="${hX}" y="${y}" fill="#ffffff" font-family="sans-serif" font-size="46" font-weight="bold" ${textDir}>${line}</text>`;
}).join("");

const sublineSvgNodes = subLines.map((line, idx) => {
  const y = 240 + (hLines.length * 56) + 30 + idx * 36;
  return `<text x="${subX}" y="${y}" fill="#cbd5e1" font-family="sans-serif" font-size="26" ${textDir}>${line}</text>`;
}).join("");

let svgContent = "";

if (mode === "existing_drive_image") {
  svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="#0f172a"/>
  <rect width="100%" height="100%" fill="rgba(15,23,42,0.80)"/>
  <rect x="40" y="40" width="1120" height="550" fill="none" stroke="${primaryColor}" stroke-width="2" rx="16"/>
  <text x="${brandX}" y="100" fill="${primaryColor}" font-family="sans-serif" font-size="24" font-weight="bold" ${brandAnchor}>${brandName}</text>
  ${headlineSvgNodes}
  ${sublineSvgNodes}
</svg>`;
} else if (mode === "render_from_template") {
  svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs>
    <linearGradient id="cardGrad" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#1e1b4b"/>
      <stop offset="100%" stop-color="#0f172a"/>
    </linearGradient>
  </defs>
  <rect width="100%" height="100%" fill="url(#cardGrad)"/>
  <rect x="40" y="40" width="1120" height="550" fill="#1e293b" fill-opacity="0.6" stroke="${primaryColor}" stroke-width="3" rx="20"/>
  <rect x="${isRtl ? 840 : 80}" y="80" width="240" height="48" fill="${primaryColor}" rx="8"/>
  <text x="${isRtl ? 960 : 200}" y="112" fill="#ffffff" font-family="sans-serif" font-size="18" font-weight="bold" text-anchor="middle">${brandName.toUpperCase()}</text>
  ${headlineSvgNodes}
  ${sublineSvgNodes}
  <line x1="80" y1="520" x2="1120" y2="520" stroke="#334155" stroke-width="2"/>
</svg>`;
} else {
  svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs>
    <linearGradient id="bgGrad" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0f172a"/>
      <stop offset="50%" stop-color="#1e293b"/>
      <stop offset="100%" stop-color="#0369a1"/>
    </linearGradient>
  </defs>
  <rect width="100%" height="100%" fill="url(#bgGrad)"/>
  <rect x="60" y="60" width="1080" height="510" fill="none" stroke="${primaryColor}" stroke-width="4" rx="16"/>
  <text x="${brandX}" y="120" fill="${primaryColor}" font-family="sans-serif" font-size="24" font-weight="bold" ${brandAnchor}>${brandName}</text>
  ${headlineSvgNodes}
  ${sublineSvgNodes}
</svg>`;
}

const binaryBuffer = Buffer.from(svgContent, "utf-8");
const base64Data = binaryBuffer.toString("base64");

return {
  json: {
    jobId: p.jobId,
    assetKey: p.assetKey,
    assetType: p.assetType,
    language: p.language,
    sourceMode: mode,
    width,
    height,
    fileSizeBytes: binaryBuffer.length,
    mimeType: "image/svg+xml",
    checksum: "",
    ok: true
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: "image/svg+xml",
      fileName: `${p.assetKey}.svg`,
      fileExtension: "svg",
      fileSize: `${binaryBuffer.length} B`
    }
  }
};

const item = $input.item;
const meta = item.json || {};
const hasBinary = item.binary && item.binary.data && item.binary.data.data;

if (!hasBinary) {
  return {
    json: {
      success: false,
      jobId: meta.jobId || null,
      assetKey: meta.assetKey || null,
      assetType: meta.assetType || null,
      status: "FAILED",
      message: "Featured image generation failed — no binary image output produced.",
      data: null,
      warnings: [],
      errors: [{ code: "RENDER_FAILED", language: null, path: null, message: "Image renderer did not produce binary output data." }],
      nextAllowedActions: ["retry", "cancel"]
    },
    binary: item.binary
  };
}

const norm = {
  success: true,
  jobId: meta.jobId,
  status: "ASSET_GENERATED",
  message: "Featured image binary generated successfully using mode: " + meta.sourceMode,
  data: {
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    sourceMode: meta.sourceMode,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    mimeType: meta.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["optimize_images"]
};

return {
  json: {
    jobId: meta.jobId,
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    language: meta.language,
    sourceMode: meta.sourceMode,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    checksum: meta.checksum,
    mimeType: meta.mimeType,
    normalized: norm
  },
  binary: item.binary
};

const j = $json || {};
const code = j.errorCode || "INVALID_INPUT";
const message = j.errorMessage || "Invalid input parameters for featured image generator.";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    assetKey: j.assetKey || null,
    assetType: j.assetType || null,
    status: "FAILED",
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
